const years = [_]u32{ 1900, 1988, 2000, 2019, 2024, 2026, 2032, 2100 };
for (years) |year| {
    const leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0);
    const result: []const u8 = if (leap) "leap year" else "common year";
    try out.print("{d}: {s}\n", .{ year, result });
